package dev.irisvisualizer.editor;

import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.function.Function;

/** Lossless nested procedural placement controls; never rotates or deforms geometry. */
public final class ProceduralTransforms {
    public static final List<String> OBJECT_FIELDS = List.of("translate", "rotation", "clamp", "stiltSettings", "vacuumSettings");
    public static final List<String> AXES = List.of("xAxis", "yAxis", "zAxis");
    private static final Properties DATA=new Properties();
    static { try (var input=ProceduralTransforms.class.getResourceAsStream("/procedural-transform-fields.properties")) { if (input==null) throw new IOException("Missing pinned procedural transform contracts");DATA.load(input);if (!"classDefaults".equals(DATA.getProperty("axis.inline.policy")) || !"ordered".equals(DATA.getProperty("clamp.range.policy"))) throw new IOException("Unsupported nested transform policy"); } catch (IOException failure) { throw new ExceptionInInitializerError(failure); } }
    private static void scope(String scope) { if (scope==null || !OBJECT_FIELDS.contains(scope) && !(scope.startsWith("rotation.") && AXES.contains(scope.substring(9)))) throw new IllegalArgumentException("Select a procedural transform owner"); }
    private static String group(String scope) { scope(scope);return scope.startsWith("rotation.") ? "axis" : scope; }
    private static String member(String scope) { scope(scope);return scope.startsWith("rotation.") ? scope.substring(9) : scope; }
    public static String prefix(ProceduralObjects.Context c,String scope) { scope(scope);return c.prefix()+scope+"."; }
    public static List<String> fields(String scope) { return List.of(DATA.getProperty(group(scope)+".fields").split(",")); }
    private static void field(String scope,String field) { if (field==null || !fields(scope).contains(field)) throw new IllegalArgumentException("Select a supported nested scalar"); }
    static String property(String scope,String field,String key) { field(scope,field);return DATA.getProperty(group(scope)+"."+field+"."+key); }
    public static String help(String scope,String field) { return property(scope,field,"description"); }
    public static String type(String scope,String field) { return property(scope,field,"type"); }
    public static String defaultValue(String scope,String field) { return property(scope,field,"default"); }
    public static String constraints(String scope,String field) { return (type(scope,field).equals("int") ? "Exact signed 32-bit integer " : "Finite number ")+property(scope,field,"minimum")+".."+property(scope,field,"maximum"); }
    public static boolean paired(String scope,String field) { scope(scope);return scope.equals("clamp") ? List.of("minimumHeight","maximumHeight").contains(field) : scope.startsWith("rotation.") && List.of("min","max").contains(field); }
    public static List<String> rangeFields(String scope) { scope(scope);if (scope.equals("clamp")) return List.of("minimumHeight","maximumHeight");if (scope.startsWith("rotation.")) return List.of("min","max");throw new IllegalArgumentException("Select a height or angle range"); }
    private static LosslessJson inline(LosslessJson parent,String member) { String token=parent.token(member);return token==null || token.equals("null") ? null : new LosslessJson(token.getBytes(StandardCharsets.UTF_8)); }
    static LosslessJson object(LosslessJson entry,String scope) { scope(scope);if (!scope.startsWith("rotation.")) return inline(entry,scope);var rotation=inline(entry,"rotation");if (rotation==null) throw new IllegalArgumentException("Enable inline rotation before its axes");return inline(rotation,member(scope)); }
    private static byte[] editSlot(byte[] raw,ProceduralObjects.Context c,String scope,Function<LosslessJson,byte[]> action) { scope(scope);return ProceduralObjects.edit(raw,c,e -> { if (!scope.startsWith("rotation.")) return action.apply(e);if (inline(e,"rotation")==null) throw new IllegalArgumentException("Enable inline rotation first");return e.objectEdit("rotation",action,false); }); }
    private static byte[] edit(byte[] raw,ProceduralObjects.Context c,String scope,Function<LosslessJson,byte[]> action) { return editSlot(raw,c,scope,parent -> { if (inline(parent,member(scope))==null) throw new IllegalArgumentException("Enable inline nested settings first");return parent.objectEdit(member(scope),action,false); }); }
    public static byte[] enable(String path,byte[] raw,ProceduralObjects.Context c,String scope) { ProceduralObjects.authorize(path,c);scope(scope);return editSlot(raw,c,scope,parent -> { if (inline(parent,member(scope))!=null) throw new IllegalArgumentException("Inline settings already exist");byte[] next=parent.enableObject(member(scope));if (!scope.startsWith("rotation.")) return next;return new LosslessJson(next).objectEdit(member(scope),ignored -> DATA.getProperty("axis."+member(scope)+".creation").getBytes(StandardCharsets.UTF_8),false); }); }
    public static byte[] reset(String path,byte[] raw,ProceduralObjects.Context c,String scope) { ProceduralObjects.authorize(path,c);scope(scope);return editSlot(raw,c,scope,parent -> { inline(parent,member(scope));return parent.token(member(scope))==null ? parent.sourceBytes() : parent.removeField(member(scope)); }); }
    static String value(LosslessJson owner,String scope,String field) { String type=type(scope,field),token=owner.token(field);if (token==null) return defaultValue(scope,field);if (type.equals("boolean")) { if (!List.of("true","false").contains(token)) throw new IllegalArgumentException("Stored scalar is not boolean");return token; }try { if (!LosslessJson.numericToken(token)) throw new NumberFormatException();var number=new BigDecimal(token);if (type.equals("int")) number.intValueExact();else if (!Double.isFinite(number.doubleValue())) throw new ArithmeticException();return token; } catch (NumberFormatException | ArithmeticException invalid) { throw new IllegalArgumentException("Stored scalar has unsupported numeric type/width",invalid); } }
    private static BigDecimal input(String scope,String field,String text) { field(scope,field);if (type(scope,field).equals("boolean")) throw new IllegalArgumentException("Use a boolean scalar");BigDecimal number;try { number=new BigDecimal(text);if (type(scope,field).equals("int")) number.intValueExact();else if (!Double.isFinite(number.doubleValue()) || number.signum()!=0 && number.doubleValue()==0) throw new ArithmeticException(); } catch (NumberFormatException | ArithmeticException | NullPointerException invalid) { throw new IllegalArgumentException("Enter a finite value with the native numeric width",invalid); }if (number.compareTo(new BigDecimal(property(scope,field,"minimum")))<0 || number.compareTo(new BigDecimal(property(scope,field,"maximum")))>0) throw new IllegalArgumentException(constraints(scope,field));return number; }
    private static byte[] put(LosslessJson owner,String scope,String field,BigDecimal number) { String old=value(owner,scope,field);if (owner.token(field)!=null && new BigDecimal(old).compareTo(number)==0) return owner.sourceBytes();return type(scope,field).equals("int") ? owner.nullableInteger(field,number.longValueExact()) : owner.token(field)==null ? owner.enable(field,number.toString()) : owner.number(field,number.doubleValue()); }
    private static void heightOrder(LosslessJson owner,String scope) { if (scope.equals("clamp") && new BigDecimal(value(owner,scope,"minimumHeight")).compareTo(new BigDecimal(value(owner,scope,"maximumHeight")))>0) throw new IllegalArgumentException("Minimum placement height must not exceed maximum; use the paired height controls"); }
    public static byte[] set(String path,byte[] raw,ProceduralObjects.Context c,String scope,String field,String text) { ProceduralObjects.authorize(path,c);field(scope,field);if (type(scope,field).equals("boolean")) { if (text==null || !List.of("true","false").contains(text)) throw new IllegalArgumentException("Choose true or false");return edit(raw,c,scope,o -> { value(o,scope,field);return o.token(field)==null ? o.enable(field,text) : o.bool(field,Boolean.parseBoolean(text)); }); }var number=input(scope,field,text);return edit(raw,c,scope,o -> { byte[] next=put(o,scope,field,number);heightOrder(new LosslessJson(next),scope);return next; }); }
    public static byte[] resetLeaf(String path,byte[] raw,ProceduralObjects.Context c,String scope,String field) { ProceduralObjects.authorize(path,c);field(scope,field);return edit(raw,c,scope,o -> { value(o,scope,field);return o.token(field)==null ? o.sourceBytes() : o.removeField(field); }); }
    public static byte[] setRange(String path,byte[] raw,ProceduralObjects.Context c,String scope,String left,String right) { ProceduralObjects.authorize(path,c);var pair=rangeFields(scope);var a=input(scope,pair.get(0),left);var b=input(scope,pair.get(1),right);if (scope.equals("clamp") && a.compareTo(b)>0) throw new IllegalArgumentException("Minimum placement height must not exceed maximum");return edit(raw,c,scope,o -> { byte[] next=put(o,scope,pair.get(0),a);return put(new LosslessJson(next),scope,pair.get(1),b); }); }
    public static byte[] resetRange(String path,byte[] raw,ProceduralObjects.Context c,String scope) { ProceduralObjects.authorize(path,c);var pair=rangeFields(scope);return resetLeaf(path,resetLeaf(path,raw,c,scope,pair.get(0)),c,scope,pair.get(1)); }
    static List<String> exclusions(LosslessJson stilt) { String token=stilt.token("exclude");return token==null || token.equals("null") ? null : stilt.stringArrayPath("exclude"); }
    public static String exclusionHelp() { return DATA.getProperty("exclude.description"); }
    private static void exclusionLimit(List<String> rows,boolean adding) { if (rows!=null && (rows.size()>64 || adding && rows.size()>=64)) throw new IllegalArgumentException("Stilt exclusions have a 64-entry editor limit"); }
    public static byte[] setExclusion(String path,byte[] raw,ProceduralObjects.Context c,int index,String text) { ProceduralObjects.authorize(path,c);if (!FloatingPlacementDeformation.materialSyntax(text) || text.indexOf(0)>=0) throw new IllegalArgumentException("Use Minecraft material key syntax without block states");return edit(raw,c,"stiltSettings",o -> { var rows=exclusions(o);exclusionLimit(rows,false);if (rows==null || index<0 || index>=rows.size()) throw new IllegalArgumentException("Select an exclusion");return rows.get(index).equals(text) ? o.sourceBytes() : o.stringArrayPath("exclude",index,text); }); }
    public static byte[] changeExclusion(String path,byte[] raw,ProceduralObjects.Context c,RiverProfiles.Action action,int index,String text) { ProceduralObjects.authorize(path,c);if (action==null) throw new IllegalArgumentException("Choose an exclusion action");if (action==RiverProfiles.Action.ADD && (!FloatingPlacementDeformation.materialSyntax(text) || text.indexOf(0)>=0)) throw new IllegalArgumentException("Use Minecraft material key syntax without block states");return edit(raw,c,"stiltSettings",o -> { var rows=exclusions(o);exclusionLimit(rows,action==RiverProfiles.Action.ADD || action==RiverProfiles.Action.DUPLICATE);if (action==RiverProfiles.Action.ADD) { if (rows==null) o=new LosslessJson(o.enableArray("exclude"));return o.stringArrayPath("exclude",rows==null ? 0 : rows.size(),text); }if (rows==null || index<0 || index>=rows.size()) throw new IllegalArgumentException("Select an existing exclusion");return switch(action) { case DUPLICATE -> o.stringArrayDuplicate("exclude",index);case REMOVE -> rows.size()==1 ? o.removeField("exclude") : o.stringArrayPath("exclude",index,null);case UP -> { if (index==0) throw new IllegalArgumentException("Already first");yield o.stringArrayMove("exclude",index,index-1); }case DOWN -> { if (index+1==rows.size()) throw new IllegalArgumentException("Already last");yield o.stringArrayMove("exclude",index,index+1); }default -> throw new IllegalArgumentException("Choose an exclusion action"); }; }); }
    public static byte[] resetExclusions(String path,byte[] raw,ProceduralObjects.Context c) { ProceduralObjects.authorize(path,c);return edit(raw,c,"stiltSettings",o -> { exclusionLimit(exclusions(o),false);return o.token("exclude")==null ? o.sourceBytes() : o.removeField("exclude"); }); }
    static List<String> readOnlyPaths(LosslessJson entry,String scope) { scope(scope);var paths=new ArrayList<String>();try { var o=object(entry,scope);if (o==null) { if (scope.startsWith("rotation.") || List.of("translate","rotation","clamp").contains(scope)) { if (scope.startsWith("rotation.") ? "null".equals(inline(entry,"rotation").token(member(scope))) : "null".equals(entry.token(scope))) paths.add(scope); }return List.copyOf(paths); }for (String f : o.fields()) { if (scope.equals("rotation") && AXES.contains(f)) paths.addAll(readOnlyPaths(entry,"rotation."+f));else if (scope.equals("stiltSettings") && f.equals("exclude")) { try { exclusionLimit(exclusions(o),false); } catch (IllegalArgumentException bad) { paths.add(scope+".exclude"); } }else if (!fields(scope).contains(f)) paths.add(scope+"."+f);else try { value(o,scope,f); } catch (IllegalArgumentException bad) { paths.add(scope+"."+f); } } } catch (IllegalArgumentException bad) { paths.add(scope); }return List.copyOf(paths); }
}
